# owner: platform
"""Weekly timesheet lines, one per worker."""

from hourglass.errors import ProjectError


def _check(shifts):
    if not shifts:
        raise ProjectError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")


def _tally(shifts):
    totals = {}
    for shift in shifts:
        name = shift.worker
        count, mins = totals.get(name, (0, 0))
        mins += shift.span.minutes
        totals[name] = (count + 1, mins)
    return totals


def _busy(item):
    return (-item[1][1], item[0])


def format_timesheet(shifts):
    """Lines like 'Ann: 2 shifts, 8.0 hours', busiest first."""
    _check(shifts)
    rows = sorted(_tally(shifts).items(), key=_busy)
    return [
        f"{name}: {count} shifts, {mins / 60:.1f} hours"
        for name, (count, mins) in rows
    ]

