# owner: platform
import unittest

from hourglass.timesheet import format_timesheet
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def make(worker, start, end):
    return Shift(worker, "mon", Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [make("Bob", 9, 10), make("Ann", 9, 12)]
        shifts.append(make("Bob", 13, 14))
        lines = format_timesheet(shifts)
        self.assertEqual(lines, [
            "Ann: 1 shifts, 3.0 hours",
            "Bob: 2 shifts, 2.0 hours"
        ])

    def test_one_decimal(self):
        shift = Shift("Cy", "tue", Span(540, 620))
        self.assertEqual(
            format_timesheet([shift]),
            ["Cy: 1 shifts, 1.3 hours"]
        )

    def test_empty_raises(self):
        with self.assertRaises(ProjectError):
            format_timesheet([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ProjectError):
            format_timesheet([make("  ", 9, 10)])
